/* ═══ INSIGHTS DA IA — gerados por regra sobre os dados reais ═══ */
const gerarInsights = (s) => {
  const out = [];
  const d = DIAS[s.diaAtual] || DIAS[1];
  const ch = CHAVES.find(c=>c.id===d.chave);

  if(s.streak >= 3)
    out.push({t:'Sua constância está construindo o resultado',
      d:`${s.streak} dias seguidos. A pesquisa de Lally mostra que a curva mais crítica da formação de hábito acontece exatamente nas primeiras três semanas — você está dentro dela.`, ico:'flame', cor:'coral'});

  if(s.checkins.length >= 2){
    const ult = s.checkins.slice(-3);
    const mediaSono = ult.reduce((a,c)=>a+(c.sono||0),0)/ult.length;
    if(mediaSono < 6.5)
      out.push({t:'Detectei um padrão no seu sono',
        d:`Sua média das últimas noites foi ${mediaSono.toFixed(1)}h. Abaixo de 7h, a grelina sobe 15% e a leptina cai 18% — você sente isso como fome extra no dia seguinte. Hoje: reforce a proteína no café e antecipe o jantar em 30 min.`, ico:'moon', cor:'violet'});
    else if(mediaSono >= 7.5)
      out.push({t:'Seu Bloco de Ouro está protegido',
        d:`Média de ${mediaSono.toFixed(1)}h nas últimas noites. É exatamente aí que 70% do GH é liberado e a leptina se restaura. Continue — este é o multiplicador de todas as outras chaves.`, ico:'moon', cor:'mint'});
  }

  if(s.medidas.length >= 2){
    const p = s.medidas[0].cintura - s.medidas[s.medidas.length-1].cintura;
    if(p > 0)
      out.push({t:`Você já destravou ${p.toFixed(1)} cm`,
        d:`Isso não é "peso perdido" — é gordura visceral e retenção viscero-linfática saindo. A balança pode nem ter se movido: recomposição corporal não aparece nela.`, ico:'ruler', cor:'pink'});
  }

  out.push({t:`Hoje trabalhamos a Chave ${String(d.chave).padStart(2,'0')} · ${ch.nome}`,
    d:ch.mecanismo, ico:'key', cor:'gold'});

  if(s.diaAtual === 14 || s.diaAtual === 7 || s.diaAtual === 21)
    out.push({t:'Hoje é dia de medição',
      d:'Refaça exatamente nas mesmas condições: ao acordar, em jejum, fita horizontal na altura do umbigo, no fim da expiração normal. Mesma luz, mesma roupa na foto.', ico:'ruler', cor:'pink'});

  return out;
};
